from bs4 import BeautifulSoup
import json, re, os
base='/mnt/data/noire-work/noire-next'
html_path=base+'/index.html'
soup=BeautifulSoup(open(html_path,encoding='utf8').read(),'html.parser')
products=[]
slugs=['signature-hoodie','women-cropped-set','women-signature-shorts','premium-tee','women-everyday-set','essential-sweatwear','dark-plum-set']
for i,card in enumerate(soup.select('.products article')):
    btn=card.select_one('.add'); img=card.select_one('.product-photo img'); meta=card.select_one('.meta')
    title=meta.select_one('span').contents[0].strip()
    subtitle=meta.select_one('small').get_text(' ',strip=True)
    products.append({'slug':slugs[i],'name':title,'cartName':btn['data-name'],'price':int(btn['data-price']),'subtitle':subtitle,'alt':img.get('alt',''),'image':img.get('src',''),'kind':card.get('data-kind',''),'description':f'{title} – {subtitle}. Ein reduzierter NOIRÉ Look aus der Collection N° 01.','details':'Designentwurf der NOIRÉ Collection N° 01. Material, Passform und verfügbare Größen werden vor dem Verkaufsstart final bestätigt.'})
open(base+'/products.json','w',encoding='utf8').write(json.dumps(products,ensure_ascii=False,separators=(',',':')))
# Link each product image/title/details to a real detail page.
for i,card in enumerate(soup.select('.products article')):
    slug=slugs[i]
    img=card.select_one('.product-photo img')
    a=soup.new_tag('a',href=f'produkt.html?product={slug}',**{'class':'product-link','aria-label':f'{products[i]["name"]} ansehen'})
    img.wrap(a)
    meta=card.select_one('.meta')
    ma=soup.new_tag('a',href=f'produkt.html?product={slug}',**{'class':'product-meta-link'})
    meta.wrap(ma)
    trigger=card.select_one('.product-details-trigger')
    trigger.string='PRODUKT ANSEHEN'
    trigger['onclick']=f"window.location.href='produkt.html?product={slug}'"
# footer links
footer=soup.footer
nav=footer.select_one('nav')
for label,href in [('IMPRESSUM','impressum.html'),('DATENSCHUTZ','datenschutz.html'),('AGB','agb.html'),('WIDERRUF','widerruf.html'),('VERSAND & ZAHLUNG','versand.html')]:
    a=soup.new_tag('a',href=href); a.string=label; nav.append(a)
# Add product image click affordance + styles
style='''\n.product-link{display:block;cursor:pointer}.product-link img{display:block;cursor:pointer}.product-meta-link{display:block;color:inherit;text-decoration:none}.product-meta-link:hover{opacity:.78}.product-details-trigger{cursor:pointer}\nfooter nav{display:flex;flex-wrap:wrap;justify-content:center;gap:16px}\n'''
soup.head.append(soup.new_tag('style')); soup.head.style.string=style
open(html_path,'w',encoding='utf8').write(str(soup))
# update main script for image clicks and open bag deep link
js=open(base+'/script.js',encoding='utf8').read()
# Replace card click handlers to navigate; add button continues to show size modal.
old='''  $$(".products article").forEach(card => {\n    const open = (event) => openProduct(card,event.currentTarget);\n    $(".add",card)?.addEventListener("click",open);\n    $(".product-details-trigger",card)?.addEventListener("click",open);\n  });'''
new='''  $$(".products article").forEach(card => {\n    const link = $(".product-link",card);\n    const details = $(".product-details-trigger",card);\n    const open = (event) => { event.preventDefault(); window.location.href = link?.href || "#shop"; };\n    link?.addEventListener("click",open);\n    details?.addEventListener("click",open);\n    $(".add",card)?.addEventListener("click",event=>{ event.preventDefault(); openProduct(card,event.currentTarget); });\n  });'''
if old not in js: print('WARNING handler block not found')
else: js=js.replace(old,new)
js=js.replace('  renderBag();\n})();','  renderBag();\n  if (new URLSearchParams(window.location.search).get("bag") === "1") openBag();\n})();')
open(base+'/script.js','w',encoding='utf8').write(js)
# product detail page
product_html='''<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#171411"><title>Produkt | NOIRÉ</title><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600&family=Italiana&display=swap" rel="stylesheet"><link rel="stylesheet" href="styles.css"><style>
.product-page{max-width:1180px;margin:50px auto 100px;padding:0 5vw;display:grid;grid-template-columns:1.1fr .9fr;gap:7vw;align-items:start}.product-page-image{width:100%;display:block;aspect-ratio:4/5;object-fit:cover;background:#eee}.product-page-copy{position:sticky;top:40px;padding-top:35px}.product-page-copy h1{font-family:Italiana,serif;font-weight:400;font-size:clamp(34px,4vw,58px);margin:12px 0}.product-page-copy .sub{color:#817a70;letter-spacing:.08em;text-transform:uppercase;font-size:12px}.product-page-price{font-size:22px;margin:24px 0}.product-page-copy label{display:block;font-size:11px;letter-spacing:.16em;margin:25px 0 9px}.product-page-copy select{width:100%;padding:16px;border:1px solid #c9c2b8;background:transparent;font:inherit}.product-page-copy button{width:100%;margin-top:18px;padding:17px;background:#171411;color:#fff;border:0;letter-spacing:.14em;cursor:pointer}.product-page-copy .feedback{min-height:24px;color:#8c4038;font-size:13px}.product-page-copy .back{display:inline-block;margin-top:25px;color:#4d4943;font-size:12px;letter-spacing:.12em}.product-page-note{font-size:12px;line-height:1.7;color:#817a70;margin-top:30px}.product-breadcrumb{max-width:1180px;margin:30px auto 0;padding:0 5vw;font-size:11px;letter-spacing:.13em;color:#817a70}.product-breadcrumb a{color:inherit}@media(max-width:760px){.product-page{grid-template-columns:1fr;gap:24px;margin-top:20px}.product-page-copy{position:static;padding-top:0}.product-page-image{aspect-ratio:4/4.5}}
</style></head><body><div class="topline">COLLECTION N° 01 <span>·</span> EVERYDAY LUXURY</div><header><a class="wordmark" href="index.html">NOIRÉ</a><nav><a href="index.html#men">HERREN</a><a href="index.html#women">DAMEN</a><a href="index.html#shop">SHOP</a></nav><a class="bag" href="index.html?bag=1">BAG</a></header><div class="product-breadcrumb"><a href="index.html">NOIRÉ</a> / <a href="index.html#shop">COLLECTION N° 01</a> / <span id="crumb">PRODUKT</span></div><main class="product-page"><div><img class="product-page-image" id="productImage" alt="NOIRÉ Produkt"></div><section class="product-page-copy"><p class="eyebrow">NOIRÉ · COLLECTION N° 01</p><h1 id="productName">NOIRÉ</h1><p class="sub" id="productSubtitle"></p><p class="product-page-price" id="productPrice"></p><p id="productDescription"></p><label for="productSize">GRÖSSE WÄHLEN</label><select id="productSize"><option value="">Bitte Größe wählen</option><option>XS</option><option>S</option><option>M</option><option>L</option><option>XL</option><option>XXL</option></select><p class="feedback" id="feedback" aria-live="polite"></p><button id="addToBag">IN DIE BAG LEGEN</button><p class="product-page-note">Größen und Materialangaben sind derzeit vorläufige Shop-Daten. Die endgültigen Produktdetails werden vor dem Verkaufsstart ergänzt.</p><a class="back" href="index.html#shop">← ZURÜCK ZUR COLLECTION</a></section></main><footer><a class="foot-logo" href="index.html">NOIRÉ</a><p>THE ART OF MODERN LUXURY</p><nav><a href="impressum.html">IMPRESSUM</a><a href="datenschutz.html">DATENSCHUTZ</a><a href="agb.html">AGB</a><a href="widerruf.html">WIDERRUF</a><a href="versand.html">VERSAND & ZAHLUNG</a></nav><small>© 2026 NOIRÉ</small></footer><script src="produkt.js"></script></body></html>'''
open(base+'/produkt.html','w',encoding='utf8').write(product_html)
product_js='''(async()=>{const money=new Intl.NumberFormat('de-DE',{style:'currency',currency:'EUR'});const slug=new URLSearchParams(location.search).get('product');const products=await fetch('products.json').then(r=>r.json());const p=products.find(x=>x.slug===slug);if(!p){document.querySelector('main').innerHTML='<h1>Produkt nicht gefunden</h1><a href="index.html#shop">Zur Collection</a>';return;}document.title=p.name+' | NOIRÉ';document.getElementById('crumb').textContent=p.name.toUpperCase();document.getElementById('productImage').src=p.image;document.getElementById('productImage').alt=p.alt;document.getElementById('productName').textContent=p.name;document.getElementById('productSubtitle').textContent=p.subtitle;document.getElementById('productPrice').textContent=money.format(p.price);document.getElementById('productDescription').textContent=p.description;document.getElementById('addToBag').addEventListener('click',()=>{const size=document.getElementById('productSize').value;const feedback=document.getElementById('feedback');if(!size){feedback.textContent='Bitte wähle zuerst deine Größe.';return;}const key='noire-bag-v2';let cart=[];try{cart=JSON.parse(localStorage.getItem(key)||'[]')}catch{}const found=cart.find(x=>x.name===p.cartName&&x.size===size);if(found)found.quantity++;else cart.push({name:p.cartName,price:p.price,size,quantity:1});localStorage.setItem(key,JSON.stringify(cart));feedback.style.color='#486b50';feedback.textContent='Zur Bag hinzugefügt. Deine Auswahl wurde gespeichert.';document.getElementById('addToBag').textContent='WEITER EINKAUFEN';document.getElementById('addToBag').onclick=()=>location.href='index.html?bag=1';});})();'''
open(base+'/produkt.js','w',encoding='utf8').write(product_js)
# legal pages: clearly mark required seller data placeholders; never fabricate identity/address
legal_style='''<style>.legal{max-width:850px;margin:70px auto 100px;padding:0 6vw;line-height:1.8;color:#34312d}.legal h1{font:400 clamp(36px,5vw,58px) Italiana,serif}.legal h2{font:400 23px Italiana,serif;margin-top:35px}.legal .placeholder{padding:12px 16px;background:#f3eee7;border-left:3px solid #b49a76}.legal small{color:#777}.legal a{color:inherit}</style>'''
def legal_page(title,body,slug):
    return f'''<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | NOIRÉ</title><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600&family=Italiana&display=swap" rel="stylesheet"><link rel="stylesheet" href="styles.css">{legal_style}</head><body><div class="topline">NOIRÉ · THE ART OF MODERN LUXURY</div><header><a class="wordmark" href="index.html">NOIRÉ</a><nav><a href="index.html#shop">SHOP</a><a href="versand.html">VERSAND & ZAHLUNG</a></nav><a class="bag" href="index.html?bag=1">BAG</a></header><main class="legal"><p class="eyebrow">NOIRÉ · INFORMATIONEN</p><h1>{title}</h1>{body}<p><a href="index.html">← Zurück zum Shop</a></p></main><footer><a class="foot-logo" href="index.html">NOIRÉ</a><p>THE ART OF MODERN LUXURY</p><nav><a href="impressum.html">IMPRESSUM</a><a href="datenschutz.html">DATENSCHUTZ</a><a href="agb.html">AGB</a><a href="widerruf.html">WIDERRUF</a><a href="versand.html">VERSAND & ZAHLUNG</a></nav><small>© 2026 NOIRÉ</small></footer></body></html>'''
placeholder='<p class="placeholder"><strong>Vor Veröffentlichung ausfüllen:</strong> Die markierten Angaben sind Pflichtangaben bzw. hängen von deiner tatsächlichen Unternehmensform und deinen eingesetzten Diensten ab. Diese Vorlage ist noch keine veröffentlichungsfertige Rechtsberatung.</p>'
open(base+'/impressum.html','w',encoding='utf8').write(legal_page('Impressum',placeholder+'''<h2>Angaben gemäß § 5 DDG</h2><p>[Vollständiger Vor- und Nachname / Firma mit Rechtsform]<br>[Straße und Hausnummer]<br>[PLZ und Ort]<br>Deutschland</p><h2>Kontakt</h2><p>E-Mail: [geschäftliche E-Mail-Adresse]<br>Telefon: [Telefonnummer, falls vorhanden]</p><h2>Weitere Pflichtangaben</h2><p>[Umsatzsteuer-Identifikationsnummer, falls vorhanden]<br>[Registergericht und Registernummer, falls eingetragen]<br>[Vertretungsberechtigte Person, falls Gesellschaft]</p><h2>Verantwortlich für den Inhalt</h2><p>[Name und ladungsfähige Anschrift, sofern erforderlich]</p><small>Vor Livegang anhand deiner tatsächlichen Unternehmensdaten und Rechtsform prüfen lassen.</small>''','impressum'))
open(base+'/datenschutz.html','w',encoding='utf8').write(legal_page('Datenschutzerklärung',placeholder+'''<p>Diese Seite muss vor dem Livegang auf die tatsächlich eingesetzten Dienste und Datenflüsse angepasst werden. Insbesondere Hosting, Server-Logs, Kontaktwege, Cookies/Local Storage, Zahlungsdienstleister und Analyse- oder Marketingtools müssen korrekt beschrieben werden.</p><h2>Verantwortlicher</h2><p>[Name/Firma, vollständige Anschrift, E-Mail]</p><h2>Hosting und Server-Logfiles</h2><p>[Hosting-Anbieter, Zweck, Rechtsgrundlage, Speicherdauer und ggf. Drittlandtransfer ergänzen.]</p><h2>Warenkorb und lokale Speicherung</h2><p>Der Shop speichert die ausgewählten Warenkorb-Artikel im Local Storage deines Browsers, damit deine Auswahl beim nächsten Seitenaufruf erhalten bleibt. [Prüfen und mit dem finalen Shopbetrieb abgleichen.]</p><h2>Bestellungen und Zahlungsabwicklung</h2><p>[Stripe und alle tatsächlich aktivierten Zahlungsmethoden, Datenkategorien, Empfänger, Rechtsgrundlage und Datenschutzhinweise des Zahlungsdienstleisters ergänzen.]</p><h2>Deine Rechte</h2><p>Du hast im gesetzlichen Rahmen Rechte auf Auskunft, Berichtigung, Löschung, Einschränkung der Verarbeitung, Datenübertragbarkeit und Widerspruch sowie das Recht auf Beschwerde bei einer Datenschutzaufsichtsbehörde.</p><h2>Kontakt zum Datenschutz</h2><p>[Kontaktadresse für Datenschutzanfragen]</p>''','datenschutz'))
open(base+'/agb.html','w',encoding='utf8').write(legal_page('Allgemeine Geschäftsbedingungen',placeholder+'''<h2>1. Geltungsbereich</h2><p>[Verkäufer mit vollständigem Namen/Firma und Anschrift] – nachfolgend „Verkäufer“ – bietet über diesen Onlineshop Waren an. Diese AGB gelten für Bestellungen von Verbraucherinnen und Verbrauchern, soweit gesetzlich zulässig.</p><h2>2. Vertragsschluss</h2><p>Die Produktdarstellungen sind eine Aufforderung zur Abgabe einer Bestellung. Der konkrete Ablauf und der Zeitpunkt des Vertragsschlusses müssen mit dem eingesetzten Checkout abgestimmt werden.</p><h2>3. Preise und Versandkosten</h2><p>Alle Preise, Umsatzsteuerangaben und Versandkosten müssen im Shop und Checkout transparent und rechtlich korrekt ausgewiesen werden.</p><h2>4. Zahlung</h2><p>Die im Checkout tatsächlich angebotenen Zahlungsarten werden vor Abschluss der Bestellung angezeigt. Zahlungsabwicklung ggf. über Stripe.</p><h2>5. Lieferung</h2><p>Liefergebiet, Lieferzeiten, Versandkosten und Umgang mit nicht verfügbaren Artikeln: [konkret ergänzen].</p><h2>6. Eigentumsvorbehalt</h2><p>[Regelung rechtlich prüfen und ergänzen.]</p><h2>7. Mängelhaftung</h2><p>Es gelten die gesetzlichen Mängelhaftungsrechte.</p><h2>8. Streitbeilegung</h2><p>[Aktuelle gesetzliche Informationspflichten und ggf. Teilnahme/Nichtteilnahme an Verbraucherschlichtung prüfen.]</p>''','agb'))
open(base+'/widerruf.html','w',encoding='utf8').write(legal_page('Widerruf & Musterformular',placeholder+'''<p>Verbraucher haben bei Fernabsatzverträgen grundsätzlich ein gesetzliches Widerrufsrecht von 14 Tagen, soweit keine gesetzliche Ausnahme greift. Die folgende Vorlage muss mit den tatsächlichen Verkäufer- und Rücksendedaten ergänzt und vor Livegang geprüft werden.</p><h2>Widerrufsbelehrung – Entwurf</h2><p>Du hast das Recht, binnen vierzehn Tagen ohne Angabe von Gründen diesen Vertrag zu widerrufen. Die Widerrufsfrist beträgt vierzehn Tage ab dem Tag, an dem du oder ein von dir benannter Dritter, der nicht Beförderer ist, die Waren in Besitz genommen hat.</p><p>Um dein Widerrufsrecht auszuüben, musst du uns ([vollständiger Name/Firma], [Anschrift], [E-Mail]) mittels einer eindeutigen Erklärung über deinen Entschluss informieren. Du kannst dafür das Muster-Widerrufsformular verwenden; dies ist jedoch nicht vorgeschrieben.</p><p>Zur Wahrung der Widerrufsfrist reicht es aus, dass du die Mitteilung vor Ablauf der Frist absendest.</p><h2>Folgen des Widerrufs</h2><p>[Gesetzeskonforme Rückzahlungs-, Rücksendekosten- und Fristenregelungen vollständig ergänzen.]</p><h2>Muster-Widerrufsformular</h2><p>An [Name/Firma und Rücksendeanschrift], E-Mail [Adresse]:<br>Hiermit widerrufe(n) ich/wir (*) den von mir/uns (*) abgeschlossenen Vertrag über den Kauf der folgenden Waren (*) …<br>Bestellt am (*) / erhalten am (*) …<br>Name des/der Verbraucher(s) …<br>Anschrift des/der Verbraucher(s) …<br>Unterschrift (nur bei Mitteilung auf Papier) …<br>Datum …<br>(*) Unzutreffendes streichen.</p>''','widerruf'))
open(base+'/versand.html','w',encoding='utf8').write(legal_page('Versand & Zahlungsmethoden',placeholder+'''<h2>Versandgebiet</h2><p>[Deutschland / weitere Länder und Ausschlüsse ergänzen.]</p><h2>Versandkosten und Lieferzeit</h2><p>[Versanddienstleister, konkrete Versandkosten, Lieferzeit und ggf. kostenfreie Versandgrenze eintragen. Diese Angaben müssen mit dem Stripe-Versandtarif übereinstimmen.]</p><h2>Zahlungsmethoden</h2><p>Im Checkout können – abhängig von deiner finalen Stripe-Konfiguration und der Verfügbarkeit für die Bestellung – Kartenzahlung sowie weitere freigeschaltete Zahlungsarten wie Klarna angezeigt werden. Apple Pay und Google Pay können bei entsprechender Stripe-/Domain-Konfiguration über unterstützte Karten-Wallets verfügbar sein.</p><p><strong>Hinweis:</strong> Es werden nur die Zahlungsarten angeboten, die im Live-Stripe-Konto aktiviert und für den jeweiligen Kauf zulässig sind.</p><h2>Retouren</h2><p>Informationen zum gesetzlichen Widerruf findest du unter <a href="widerruf.html">Widerruf</a>. Die konkrete Rücksendeadresse und praktische Retourenabwicklung: [ergänzen].</p>''','versand'))
